python3 - "$research_dir" <<'"'PY'
from bs4 import BeautifulSoup
from pathlib import Path
import sys
for name in ['school_sob.html','school_sobs.html','school_soe.html','school_soh.html','school_soljg.html','school_som.html','school_sovs.html','USICT_index.html.html']:
 p=Path(sys.argv[1])/name
 soup=BeautifulSoup(p.read_text(errors='ignore'),'html.parser')
 print('\\n###',name)
 for ti,t in enumerate(soup.find_all('table')):
  rows=[]
  for tr in t.find_all('tr'):
   cells=[' '.join(c.get_text(' ',strip=True).split()) for c in tr.find_all(['th','td'])]
   if cells: rows.append(cells)
  if rows:
   print('TABLE',ti,'rows',len(rows),'header=',rows[0])
   for row in rows[1:]:
    print(' | '.join(row))
PY"

