from bs4 import BeautifulSoup
from pathlib import Path
import json, sqlite3, sys
from collections import defaultdict

root=Path(sys.argv[1])
# Read only from the independently fetched official current programme-list pages.
rows=[]
for page in range(1,9):
    s=BeautifulSoup((root/f'eligible-{page}.html').read_text(errors='ignore'),'html.parser')
    for tr in s.select('tr[data-key]'):
        td=tr.find_all('td',recursive=False)
        if len(td)<3: continue
        number=' '.join(td[0].get_text(' ',strip=True).split())
        name=' '.join(td[1].get_text(' ',strip=True).split())
        eligibility=' '.join(td[2].get_text(' ',strip=True).split())
        if not name: continue
        rows.append({'number':int(number),'name':name,'eligibility':eligibility,'page':page})

# Read-only career tree lookup and exact breadcrumbs.
con=sqlite3.connect(f'file:assets/data/career_path.db?mode=ro', uri=True)
node_rows=con.execute('select id,slug,parent_id,name from career_nodes').fetchall()
by_id={r[0]:r for r in node_rows}
def breadcrumb(node_id):
    parts=[]; seen=set(); cur=node_id
    while cur is not None and cur not in seen:
        seen.add(cur); row=by_id[cur]; parts.append(row[3]); cur=row[2]
    return ' > '.join(reversed(parts))

nodes={
    'btech':(1,'btech'), 'bsc_maths':(2,'bsc_maths'), 'bca':(3,'bca'),
