    'bsc_bio':(21,'bsc_bio'), 'bsc_stats':(6,'bsc_stats'),
    'bams':(17,'bams'), 'bcom':(42,'bcom'), 'bba':(46,'bba'),
    'bdes':(55,'bdes'), 'barch':(56,'barch'), 'bjmc':(59,'bjmc'),
    'ba_llb':(63,'ba_llb'), 'ba_psychology':(66,'ba_psychology'),
    'ba_sociology':(67,'ba_sociology'), 'ba_economics':(68,'ba_economics'),
    'ba_education':(69,'ba_education'), 'ba_history':(70,'ba_history'),
    'ba_polsci':(71,'ba_polsci'), 'ba_english':(72,'ba_english'),
    'ba_hindi':(73,'ba_hindi'), 'sports_career':(78,'sports_career'),
    'msc_maths':(90,'msc_maths'), 'mca':(93,'mca'), 'bplan_sci':(107,'bplan_sci'),
    'btech_cs':(80,'btech_cs'), 'btech_ai':(81,'btech_ai'),
    'btech_ece':(82,'btech_ece'), 'btech_mech':(83,'btech_mech'),
    'btech_civil':(84,'btech_civil'), 'btech_electrical':(85,'btech_electrical'),
    'btech_biotech':(88,'btech_biotech'), 'btech_it':(89,'btech_it'),
    'msc_biotech':(146,'msc_biotech'), 'msc_physics':(153,'msc_physics'),
    'msc_chemistry':(155,'msc_chemistry'), 'data_product_manager':(170,'data_product_manager'),
    'microbiologist':(177,'microbiologist'), 'social_worker':(269,'social_worker'),
    'fitness_trainer':(370,'fitness_trainer'), 'child_psychologist':(373,'child_psychologist'),
    'textile_designer':(237,'textile_designer'), 'interior_design':(233,'interior_design'),
    'art_social':(348,'art_social'), 'art_languages':(349,'art_languages'),
    'mba_general':(208,'mba_general'), 'urban_planning':(234,'urban_planning'),
}

def direct(key, confidence='high', relation='direct_discipline'):
    node_id,slug=nodes[key]
    return node_id,slug,relation,confidence

def map_course(name):
    n=name.lower()
    # Explicitly named non-degree programmes first.
    if 'child guidance' in n: return direct('child_psychologist')
    if 'gym instructor' in n: return direct('fitness_trainer')
    if 'pali' in n: return direct('art_languages','low','nearest_parent')
    if 'heritage restoration' in n: return direct('barch','medium','closest_specialization')
    if 'b.des. (interior' in n or 'interior design' in n: return direct('interior_design')
    if 'textile design' in n: return direct('textile_designer')
    if 'master of design' in n: return direct('bdes','medium','closest_specialization')
    if 'urban and regional planning' in n or 'b. plan' in n: return direct('bplan_sci')
    if 'b.a. b.ed' in n or 'b.com. b.ed' in n or 'b.sc. b.ed' in n: return direct('ba_education')
    if 'dual degree bba' in n: return direct('bba')
    if 'business analytics and data science' in n:
        return direct('data_product_manager','medium','closest_specialization')
    if 'doctor of philosophy (management)' in n: return direct('mba_general','medium','closest_specialization')
    if n == 'mba' or 'mba (executive)' in n: return direct('mba_general')
    if 'bachelor of commerce' in n: return direct('bcom')
    if 'biotechnology' in n:
        if ('master of science' in n and 'biotechnology' in n) or 'research in biotechnology' in n:
            return direct('msc_biotech')
        return direct('btech_biotech')
    if 'forensic science' in n: return direct('bsc_forensic')
    if 'ayurveda biology' in n: return direct('bams','medium','closest_specialization')
    if 'microbiology' in n: return direct('bsc_microbio')
    if 'life sciences' in n: return direct('bsc_bio','medium','closest_specialization')
    if 'nuclear medicine' in n: return direct('bsc_bio','medium','closest_specialization')
    if 'buddhist studies' in n: return direct('art_social','low','nearest_parent')
    if 'll.m' in n or 'master of laws' in n or 'ph.d (law)' in n or 'ph.d. (law)' in n: return direct('ba_llb','medium','closest_specialization')
    if 'ba llb' in n: return direct('ba_llb')
    if 'architecture' in n and 'technology' not in n: return direct('barch')
    if 'electronics and communication' in n or 'ece' in n or 'vlsi' in n or 'iot and robotics' in n: return direct('btech_ece')
    if 'computer science' in n or 'cse' in n:
        if 'artificial intelligence' in n and 'cse' in n: return direct('btech_ai','medium','closest_specialization')
        return direct('btech_cs')
    if 'information technology' in n or n.endswith('(it)') or 'technology (it)' in n: return direct('btech_it')
    if 'computer application' in n:
        if 'master' in n or 'mca' in n: return direct('mca')
        return direct('bca')
    if 'food processing' in n or 'food science' in n: return direct('bsc_food_tech')
    if 'maths and computing' in n: return direct('btech_cs','medium','closest_specialization')
    if 'geospatial data science' in n: return direct('bsc_ds','medium','closest_specialization')
    if 'operations research' in n: return direct('bsc_cs','medium','closest_specialization')
    if 'applied chemistry' in n or 'chemistry' in n:
        if 'm.sc' in n or 'master of science' in n or 'ph.d' in n: return direct('msc_chemistry')
        return direct('bsc_chemistry')
    if 'physics' in n:
        if 'm.sc' in n or 'master of science' in n: return direct('msc_physics')
        return direct('bsc_physics')
    if 'mathematics' in n:
        if 'm.sc' in n or 'master of science' in n or 'ph.d' in n: return direct('msc_maths')
        return direct('bsc_maths')
    if 'environmental' in n: return direct('bsc_env')
    if 'electrical' in n or 'power electronics' in n or 'power systems' in n or 'renewable energy' in n or 'instrumentation and control' in n: return direct('btech_electrical')
    if 'civil' in n or 'construction management' in n or 'structural engineering' in n or 'transportation engineering' in n: return direct('btech_civil')
    if 'mechanical' in n or 'manufacturing engineering' in n or 'thermal engineering' in n: return direct('btech_mech')
    if 'physical education' in n or 'bpes' in n or 'mpes' in n: return direct('sports_career')
    if 'political' in n: return direct('ba_polsci')
    if 'history' in n: return direct('ba_history')
    if 'english' in n: return direct('ba_english')
    if 'hindi' in n or 'urdu' in n: return direct('ba_hindi')
    if 'journalism' in n or 'mass communication' in n: return direct('bjmc')
    if 'social work' in n: return direct('social_worker')
    if 'psychology' in n: return direct('ba_psychology')
    if 'sociology' in n: return direct('ba_sociology')
    if 'economics' in n: return direct('ba_economics')
    if 'education' in n or 'b. ed' in n: return direct('ba_education')
    if 'library' in n: return direct('art_social','low','nearest_parent')
    if 'hindu studies' in n: return direct('art_social','low','nearest_parent')
    if 'human rights' in n: return direct('ba_polsci','medium','closest_specialization')
    # General engineering/doctoral fallback only if clearly identifiable.
    if 'bachelor of technology' in n or 'b.tech' in n or 'm.tech' in n or 'doctor of philosophy' in n or 'ph.d' in n:
        return direct('btech','low','nearest_parent')
    return None

def classify(name):
    n=name.lower()
    if 'foundation course' in n: return 'other','foundation course'
    if 'certificate' in n and 'diploma' not in n: return 'certificate','Certificate'
    if 'diploma' in n: return 'diploma','Post Graduate Diploma' if 'post graduate' in n or 'pg diploma' in n else 'Diploma'
    if 'ph.d' in n or 'doctor of philosophy' in n: return 'doctoral','Ph.D.'
    if 'dual degree' in n or 'integrated' in n or 'b.a. b.ed' in n or 'b.com. b.ed' in n or 'b.sc. b.ed' in n: return 'integrated','Integrated degree'
    if any(x in n for x in ('m.tech','master of technology','m.sc','master of science','m.a.','master of arts','mba','master in computer','master of laws','ll.m','m.plan','master of design','master of physical','master of social','master of library')):
        if 'mba' in n: return 'postgraduate','MBA'
        if 'm.tech' in n or 'master of technology' in n: return 'postgraduate','M.Tech.'
        if 'm.sc' in n or 'master of science' in n: return 'postgraduate','M.Sc.'
        if 'll.m' in n or 'master of laws' in n: return 'postgraduate','LL.M.'
        if 'm.plan' in n: return 'postgraduate','M.Plan'
        if 'master of design' in n: return 'postgraduate','M.Des.'
        if 'master of physical' in n: return 'postgraduate','MPES'
        if 'master of social' in n: return 'postgraduate','MSW'
        if 'master of library' in n: return 'postgraduate','M.Lib.I.Sc.'
        return 'postgraduate','M.A.'
    if 'b.tech' in n or 'bachelor of technology' in n: return 'undergraduate','B.Tech.'
    if 'b.arch' in n or 'bachelor of architecture' in n: return 'undergraduate','B.Arch.'
    if 'b.des' in n or 'bachelor of design' in n: return 'undergraduate','B.Des.'
    if 'bca' in n or 'computer application' in n: return 'undergraduate','BCA'
    if 'b.com' in n or 'bachelor of commerce' in n: return 'undergraduate','B.Com.'
    if 'b.a.' in n or 'bachelor of arts' in n: return 'undergraduate','B.A.'
    if 'b.sc' in n or 'bachelor of science' in n: return 'undergraduate','B.Sc.'
    if 'bachelor of social work' in n: return 'undergraduate','BSW'
    if 'bachelor of physical' in n: return 'undergraduate','BPES'
    return 'other','programme'

courses=[]; unmapped=[]
for row in rows:
    mapped=map_course(row['name'])
    if mapped is None:
        unmapped.append(row['name'])
        maps=[]; gap='No responsible career-tree node identified from the local tree.'
    else:
        node_id,slug,relation,confidence=mapped
        maps=[{
            'career_node_id':node_id,
            'career_node_slug':slug,
            'career_breadcrumb':breadcrumb(node_id),
            'relation':relation,
            'confidence':confidence,
            'mapping_status':'reviewed_against_local_tree'
        }]
        gap=None
    level,credential=classify(row['name'])
    mode='weekend/working professional' if ('working professional' in row['name'].lower() or 'weekend' in row['name'].lower()) else 'not_specified'
    courses.append({
        'course_id':f'gbu-2026-{row[\"number\"]:03d}',
        'name':row['name'],
        'level':level,
        'credential':credential,
        'specialization':None,
        'duration':None,
        'mode':mode,
        'eligibility':row['eligibility'],
        'official_course_url':f'https://gbuadm.samarth.edu.in/index.php/site/eligible-programme-list?page={row[\"page\"]}',
        'verification_status':'verified',
        'career_path_mappings':maps,
        'mapping_gap':gap
    })

