def classify(name):
    n=name.lower()
    if 'foundation course' in n: return 'other','foundation course'
    if 'certificate' in n and 'diploma' not in n: return 'certificate','Certificate'
    if 'diploma' in n: return 'diploma','Post Graduate Diploma' if 'post graduate' in n or 'pg diploma' in n else 'Diploma'
    if 'ph.d' in n or 'doctor of philosophy' in n: return 'doctoral','Ph.D.'
    if 'dual degree' in n or 'integrated' in n or 'b.a. b.ed' in n or 'b.com. b.ed' in n or 'b.sc. b.ed' in n: return 'integrated','Integrated degree'
    if any(x in n for x in ('m.tech','master of technology','m.sc','master of science','m.a.','master of arts','mba','master in computer','master of laws','ll.m','m.plan','master of design','master of physical','master of social','master of library')):
        if 'mba' in n: return 'postgraduate','MBA'
        if 'm.tech' in n or 'master of technology' in n: return 'postgraduate','M.Tech.'
        if 'm.sc' in n or 'master of science' in n: return 'postgraduate','M.Sc.'
        if 'll.m' in n or 'master of laws' in n: return 'postgraduate','LL.M.'
        if 'm.plan' in n: return 'postgraduate','M.Plan'
        if 'master of design' in n: return 'postgraduate','M.Des.'
        if 'master of physical' in n: return 'postgraduate','MPES'
        if 'master of social' in n: return 'postgraduate','MSW'
        if 'master of library' in n: return 'postgraduate','M.Lib.I.Sc.'
        return 'postgraduate','M.A.'
    if 'b.tech' in n or 'bachelor of technology' in n: return 'undergraduate','B.Tech.'
    if 'b.arch' in n or 'bachelor of architecture' in n: return 'undergraduate','B.Arch.'
    if 'b.des' in n or 'bachelor of design' in n: return 'undergraduate','B.Des.'
    if 'bca' in n or 'computer application' in n: return 'undergraduate','BCA'
    if 'b.com' in n or 'bachelor of commerce' in n: return 'undergraduate','B.Com.'
    if 'b.a.' in n or 'bachelor of arts' in n: return 'undergraduate','B.A.'
    if 'b.sc' in n or 'bachelor of science' in n: return 'undergraduate','B.Sc.'
    if 'bachelor of social work' in n: return 'undergraduate','BSW'
    if 'bachelor of physical' in n: return 'undergraduate','BPES'
    return 'other','programme'

